def scaling():
 rr=read(P/'results/paper/final_resident864_20261016/tables/pebs_first_hit.csv');lookup={r['candidate']:r for r in rr}
 exports=[]
 for values,ids,name,xlabel in [([8,16,32,64],[f'd8_w{w}' for w in [8,16,32,64]],'filter_width_scaling','Estimator initial filter width'),(list(range(1,11)),[f'd{d}_w64' for d in range(1,11)],'network_depth_scaling','Estimator depth')]:
  picked=[lookup[k] for k in ids];assert all(r['validation_reached']=='True' for r in picked)
  times=[float(r['total_seconds']) for r in picked];counts=[int(r['total_iteration']) for r in picked];x=np.arange(len(values))
  fig,ax=plt.subplots(figsize=(3.5,2.25));right=ax.twinx()
  bars=ax.bar(x,times,width=.56,color=COL[1],edgecolor='white',linewidth=.5,label='First-hit time',zorder=2)
  line,=right.plot(x,counts,color=COL[0],marker='o',ms=4.5,lw=1.85,label='Total iterations',zorder=3)
  for xx,n in zip(x,counts):right.annotate(str(n),(xx,n),xytext=(0,5),textcoords='offset points',ha='center',fontsize=8.5,color=COL[0])
  ax.set(xlabel=xlabel,ylabel='Time to target (s)',xticks=x,xticklabels=values,ylim=(0,1.9),xlim=(-.6,len(x)-.4));ax.set_yticks([0,.5,1,1.5])
  right.set(ylabel='Total online iterations',ylim=(0,16),yticks=[0,4,8,12,16]);right.tick_params(axis='y',colors='#0072BD');right.yaxis.label.set_color('#0072BD');ax.tick_params(axis='y',colors='black');ax.yaxis.label.set_color('black')
  ax.grid(axis='both',color='#d6d6d6',lw=.5);ax.set_axisbelow(True);ax.tick_params(direction='in');right.tick_params(direction='in')
  ax.legend([bars,line],['First-hit time','Total iterations'],ncol=2,frameon=False,loc='lower center',bbox_to_anchor=(.5,1.005),borderaxespad=0,handlelength=2.4,columnspacing=1,fontsize=8.5)
  fig.subplots_adjust(left=.16,right=.85,bottom=.21,top=.86)
  finish(fig,name,'Time and total online iterations to the first seed56 monitoring BER below2e-4 at12dB; fixed depth8 for width comparison and fixed width64 for depth comparison. '+m.TIME)
  for r in picked:exports.append(dict(figure=name,candidate=r['candidate'],time_seconds=r['total_seconds'],total_iterations=r['total_iteration'],hit_stage=r['stage'],stage_iteration=r['stage_iteration'],monitor_reached=r['validation_reached']))
 with (O/'width_depth_first_hit.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(exports[0]));w.writeheader();w.writerows(exports)

def learning_rate():
 fig,ax=plt.subplots(figsize=(3.5,2.35));style(ax,'Total online iteration',False,low=7e-5,high=1.3)
 initial=read(P/'lr_initial.csv')
 for i,lr in enumerate([.01,.003,.001,.0003,.0001]):
  rr=read(P/f'results/replacement864_20261016/lr/runs/lr_{lr:g}/iterations.csv');assert len([r for r in rr if r['stage']=='est'])==5
  before=next(r for r in initial if float(r['learning_rate'])==lr)
  curve(ax,[before]+rr,'total_iteration',f'{lr:g}',[COL[1],COL[2],COL[0],COL[3],COL[4]][i],MK[i],ls='-',asset='learning_rate_iterations')
 ax.axvspan(0,5.5,color='#D9EAF4',alpha=.2,zorder=0);ax.axvline(5.5,color='#555555',lw=.8,ls='--')
 ax.annotate('dem. starts at 6',xy=(5.5,.003),xytext=(9,.0018),fontsize=8.5,arrowprops=dict(arrowstyle='->',lw=.6),ha='left')
 for text in ax.texts:
  if text.get_text().startswith('Target:'):text.set_x(.98);text.set_ha('right')
 ax.set(xticks=[0,5,10,15,20,25],xlim=(0,25.4));ax.legend(ncol=3,frameon=False,loc='lower center',bbox_to_anchor=(.5,1.005),borderaxespad=0,columnspacing=1,handlelength=2.4,labelspacing=.15);fig.subplots_adjust(left=.17,right=.99,bottom=.20,top=.82)
 finish(fig,'learning_rate_iterations','Full observed online trajectory including initial BER, estimator iterations1–5 and demapper iterations6–25. The stage boundary is5.5; demapper starts at total iteration6. Fixed-budget diagnostic: est5 plus dem20; no early stopping, even if the target is reached earlier.')
def learning():
 learning_rate()
 rr=read(P/'results/replacement864_20261016/batch64/batch32_vs64.csv');fig,ax=plt.subplots(figsize=(3.5,2.15));style(ax,'Total iteration',False,low=7e-5,high=1.3)
 for i,b in enumerate([32,64]):curve(ax,[r for r in rr if int(r['batch_size'])==b],'total_iteration',f'Batch {b}',COL[0],MK[i],ls=['-','--'][i],asset='batch32_vs64')
 ax.axvline(5.5,color='#999999',lw=.7,ls=':');ax.set(xticks=list(range(7)),xlim=(-.1,6.2));ax.legend(ncol=2,frameon=False,loc='lower center',bbox_to_anchor=(.5,1));fig.subplots_adjust(left=.17,right=.99,bottom=.22,top=.84)
 finish(fig,'batch32_vs64','Batch32 versus64 with a fixed five-iteration estimator stage plus one demapper iteration. Iteration0 is the source pretrained model; batch64 processes twice as many samples per iteration.')
def backbone():
 rr=read(B/'tables/backbone_time_curves.csv')
 if not any(r['backbone']=='CNN' for r in rr):rr += [dict(r,backbone='CNN',method='FastSET' if r['method']=='FastSET' else 'E2E') for r in read(B/'tables/main_adaptation_curve.csv')]
 fig,ax=plt.subplots(figsize=(3.5,2.55));style(ax,'Adaptation time (s)',False,low=7e-5,high=1.3)
 colors={family:color for family,color in [('CNN','#0072BD'),('Transformer','#D95319'),('MLP','#7E2F8E')]}
 for family,col,mk in [('CNN',COL[0],'o'),('Transformer',COL[2],'s'),('MLP',COL[4],'D')]:
  for method,ls in [('FastSET','-'),('E2E','--')]:
   curve(ax,[r for r in rr if r['backbone']==family and r['method']==method],'total_seconds',family+' '+method,colors[family],mk,ls,asset='backbone_time',panel=family)
   line=ax.lines[-1];n=len(line.get_xdata());line.set_linewidth(1.85)
   line.set_markevery([0,n-1] if family=='CNN' and method=='FastSET' else sorted(set(np.linspace(0,n-1,min(5,n),dtype=int).tolist())))
 ax.set_xlim(left=-.3);ax.legend(ncol=2,frameon=False,loc='lower center',bbox_to_anchor=(.5,1),columnspacing=.8,handlelength=2.4,fontsize=8.5);fig.subplots_adjust(left=.17,right=.99,bottom=.2,top=.66)
 finish(fig,'backbone_time','CNN, Transformer and MLP adaptation in one coordinate system: Three colors and markers identify CNN, Transformer and MLP; solid/dashed lines identify FastSET/E2E. The CNN-backbone FastSET curve has endpoint markers only. All recorded iterations retained. Nonconverged runs end at their budgets. '+m.TIME)
def speed():
 rr=read(P/'results/sionna_speed864_20261016/ber_curves.csv')
 import runpy
 runpy.run_path(str(Path(__file__).with_name('plot_speed.py')),run_name='__main__')
 for xmax,name,width in [(18,'speed_ber_fullrange',7.1)]:
  fig,ax=plt.subplots(figsize=(width,2.65));style(ax,xmax=xmax)
  for phase,ls in [('pretrained','--'),('adapted','-')]:
   for i,v in enumerate([5,10,20]):
    phase_label='before' if phase=='pretrained' else 'after'
    curve(ax,[r for r in rr if float(r['speed_mps'])==v and r['phase']==phase],'snr',f'{v} m/s {phase_label}',COL[[2,3,4][i]],['o','^','s'][i],ls=ls,asset=name,panel=phase)
    ax.lines[-1].set_markerfacecolor('white' if phase=='pretrained' else COL[[2,3,4][i]])
  h,l=ax.get_legend_handles_labels()
  fig.legend(h,l,ncol=2 if xmax==12 else 4,frameon=False,loc='upper center',bbox_to_anchor=(.55,1),columnspacing=.8,handlelength=2.4,labelspacing=.25)
  fig.subplots_adjust(left=.19,right=.99,bottom=.195,top=.74)
  finish(fig,name,'Speed sensitivity on fixed TDL-B500ns in one coordinate system. Color and marker identify speed; dashed/open and solid/filled curves denote before and after adaptation. '+m.ZERO,wide=xmax==18)
 EXCEPTIONS.append(dict(asset='speed_ber_fullrange',range=[4,18],reason='At14dB the adapted20m/s case has1996 errors (BER7.66089e-5), versus32/0/0 at0/5/10m/s. The high-SNR speed effect remains in the full-range supplement; main follows requested12dB window.'))
def tdl():
 root=P/'results/tdl_delay_grid_20261016';status={'status':'complete'}
 rr=read(root/'ber_curves.csv');tt=read(root/'adaptation_summary.csv');assert len(rr)==120 and len(tt)==8
 for xmax,name in [(12,'multipath_delay_ber'),(18,'multipath_delay_ber_fullrange')]:
  paired=xmax==12
  if paired:fig,(ax,right)=plt.subplots(1,2,figsize=(3.5,3.0),gridspec_kw={'width_ratios':[1,1.5]})
  else:fig,ax=plt.subplots(figsize=(3.5,2.5))
  style(ax,xmax=xmax)
  if paired:ax.set_xlim(3.6,12.4)
  if paired:
   before=read(P/'results/before_curves_side_20261016/before_curves.csv')
   for method,col,mk in [('FastSET',COL[0],MK[0]),('CNN',COL[1],MK[1])]:
    curve(ax,[r for r in before if r['case']=='delay600' and r['method']==method],'snr',method+' before',col,mk,'--',asset=name,panel='600 before')
    ax.lines[-1].set_markerfacecolor('white')
  cases=[(600,'-'),(1200,'-.')] if paired else [(600,'-'),(900,'--'),(1200,':')]
  for ns,ls in cases:
   for method,col,mk in [('FastSET',COL[0],MK[0]),('CNN',COL[1],MK[1])]:curve(ax,[r for r in rr if int(r['delay_ns'])==ns and r['method']==method],'snr',(f'{ns} '+method) if paired else (f'{ns} ns '+method),col,mk,ls,asset=name,panel=str(ns))
  if paired:
   pairs=[]
   for ns in [600,900,1200]:
    ff,cc=[next(r for r in tt if int(r['delay_ns'])==ns and r['method']==method) for method in ['FastSET','CNN']]
    assert ff['target_reached']==cc['target_reached']=='True'
    pairs.append([float(ff['total_seconds']),float(cc['total_seconds'])])
   paired_times(right,['600','900','1200'],pairs,COL[:2]);right.set_xlabel('Delay (ns)')
   h,l=ax.get_legend_handles_labels();order=[0,2,4,1,3,5];fig.legend([h[i] for i in order],[l[i] for i in order],ncol=2,frameon=False,loc='upper center',bbox_to_anchor=(.55,1),columnspacing=.65,handlelength=1.8)
   fig.subplots_adjust(left=.15,right=.98,bottom=.19,top=.74,wspace=.52)
   caption='Left: two600ns before curves and four600/1200ns after curves. Right: input-inclusive FastSET/CNN first-hit times in seconds, with ratios above the pairs at600/900/1200ns. The900ns BER curve remains in the full-range supplement. '
  else:
   ax.legend(ncol=2,frameon=False,loc='lower center',bbox_to_anchor=(.5,1),columnspacing=.8,handlelength=2.4);fig.subplots_adjust(left=.17,right=.99,bottom=.2,top=.66)
   caption='TDL-B600/900/1200ns full-range BER;300ns omitted as requested. '
  finish(fig,name,caption+'Method uses color/marker; delay uses line style. Same fixed source-A checkpoints. '+m.ZERO)
 fig,ax=plt.subplots(figsize=(3.5,2.15));ratios=[]
 for ns in [600,900,1200]:
  f,c=[next(r for r in tt if int(r['delay_ns'])==ns and r['method']==mm) for mm in ['FastSET','CNN']]
  good=all(r['target_reached']=='True' for r in [f,c]) and float(f['total_seconds'])>0;ratios.append(float(c['total_seconds'])/float(f['total_seconds']) if good else None)
 good=[v for v in ratios if v is not None];top=max(good) if good else 1
 ax.bar([i for i,v in enumerate(ratios) if v is not None],good,width=.55,color=COL[0])
 for i,v in enumerate(ratios):ax.text(i,(v or 0)+top*.025,f'{v:.2f}×' if v is not None else 'N/R',ha='center',fontsize=8.5)
 ax.set(xticks=range(3),xticklabels=[600,900,1200],xlabel='TDL delay spread (ns)',ylabel='CNN / FastSET time',ylim=(0,top*1.2));ax.grid(axis='both',color='#d6d6d6',lw=.5);ax.set_axisbelow(True);fig.subplots_adjust(left=.17,right=.99,bottom=.25,top=.95)
 finish(fig,'delay_spread_speedup','Qualified CNN/FastSET time ratios at600/900/1200ns. N/R indicates at least one method has not reached the target within budget. '+m.TIME)
 EXCEPTIONS.append(dict(asset='multipath_delay_ber_fullrange',range=[4,18],reason='Full-range supplementary curves preserve every measured tail point; main displays4–12dB.300ns omitted from both main and supplement per user.'))
def main():
 scaling();learning();backbone();speed();tdl();m.audit(O)
 (O/'DISPLAY_RANGE_EXCEPTIONS.json').write_text(json.dumps(dict(main_default=[4,12],main_display_exceptions=[],supplements=EXCEPTIONS,data_rows_removed=0,excluded_condition='TDL300ns intentionally omitted from displayed assets, measurements preserved in originalCSV'),indent=2))
 print(O)
if __name__=='__main__':main()
